double trapezoidal_integration(double (*f)(double), double a, double b, int N) {
    if (N <= 0) {
        return 0.0;
    }
    if (a == b) {
        return 0.0;
    }
    double h = (b - a) / N;
    double sum = f(a) + f(b);
    for (int i = 1; i < N; ++i) {
        sum += 2.0 * f(a + i * h);
    }
    return (h / 2.0) * sum;
}

